begin;
create function private.assert_renewal(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',msg;end if;end$$;
set test.uid='00000000-0000-0000-0000-000000000001';set test.email='admin@test.test';set test.role='authenticated';
select private.assert_renewal((full_license_quote(1,2027)->>'price')::numeric=500,'previous Full holder pays R500');
select private.assert_renewal((full_license_quote(2,2027)->>'price')::numeric=650,'temporary-only holder pays R650');
select private.assert_renewal((full_license_quote(3,2027)->>'price')::numeric=650,'first purchase pays R650');
select manage_license('save_season','{"year":2027,"price":650,"renewal_price":500,"sales_open":true,"reason":"Pricing fixture"}');
select private.assert_renewal((player_license_eligibility(3,10)->>'purchase_year')::integer=2027,'2026 event offers immediately-valid 2027 Full license');
select private.assert_renewal((player_license_eligibility(1,11)->>'full_price')::numeric=500,'future-event renewal uses R500');
select manage_license('grant','{"player_id":3,"year":2027,"source":"manual","amount":650,"payment_method":"eft","reason":"First Full purchase"}');
select private.assert_renewal(has_full_license(3,2026) and has_full_license(3,2027),'a new Full license covers this year and next');
select private.assert_renewal((select valid_from=public.license_today() from annual_licenses where player_id=3 and season_year=2027),'coverage starts immediately');
select private.assert_renewal((select license_type='full' from players where id=3),'immediate Full coverage projected');
select private.assert_renewal((select status='active' and ends_on='2027-12-31' from private.license_register where player_id=3),'register shows active coverage through December 2027');
select manage_license('grant','{"player_id":1,"year":2027,"source":"manual","amount":500,"payment_method":"eft","reason":"Renew Full license"}');
select private.assert_renewal((select count(*)=2 from annual_licenses where player_id=1),'renewal retains existing annual history');
select private.assert_renewal((select count(*)=1 from license_accounts where player_id=1),'renewal retains permanent number');
-- Honor a server-saved checkout even after the public price changes.
insert into public.players values(4,'Saved checkout','saved@test.test','none',false);
insert into public.native_license_checkouts(reference,user_id,player_id,amount,pricing,license_year,license_type) values('old-server-price','00000000-0000-0000-0000-000000000001',4,450,'{}',2027,'full');
set test.role='service_role';
insert into public.payments(player_id,amount,currency,status,payment_type,payment_method,reference,metadata) values(4,450,'ZAR','success','membership','paystack','old-confirmed-charge','{"client_reference":"old-server-price","license_type":"full","license_year":2027}');
select private.assert_renewal(has_full_license(4,2027),'saved attempt keeps its original verified price');
update public.payments set status='success' where reference='old-confirmed-charge';
select private.assert_renewal((select count(*)=1 from annual_licenses where player_id=4),'callback replay creates one license');
create or replace function public.license_today() returns date language sql stable set search_path='' as $$select '2027-01-01'::date$$;
select private.assert_renewal((full_license_quote(2,2027)->>'starts_on')::date='2027-01-01','January purchases start in January');
select private.assert_renewal((full_license_quote(2,2027)->>'ends_on')::date='2027-12-31','January purchases end in December of the same year');
select private.assert_renewal((full_license_quote(2,2027)->>'price')::numeric=650,'temporary-only holder remains a new Full buyer in January');
rollback;
